# CELL 13c: FIGURES   (Eir 2.0.13)
# ============================================================================
# Three diagnostics that Eir needs to answer its own question. Everything
# pool-level - GII against publication year, deviation by element, provenance
# by decade - stays in Huginn, which is where cross-run analysis belongs.
#
# CONVENTIONS, and they are not negotiable in a submitted figure:
#
#   - Axis labels are QUANTITY CALCULUS: "GII / v.u.", never "GII (v.u.)".
#     The label names a pure number, so the unit divides the quantity.
#   - Single column is 3.35 in and double is 6.9 in. Three panels crammed
#     across a double column gives each 2.3 in, which is a poster habit.
#   - No gridlines, no top or right spine, no frame on the legend, no
#     chartjunk. Nothing is drawn that does not carry information.
#   - Clipped values are COUNTED in an annotation, never piled into the end
#     bin: a clipped tail draws a spike that is an artefact of the clip.
#   - An absent column is not a zero. A screen that was never computed is
#     omitted rather than drawn as a bar of length nothing.
#   - 600 dpi raster; save_figure() also writes PDF, which is what to submit.
#
# Colours are the University of Sheffield brand palette. Brand violet against
# coral separates on lightness as well as hue, so it survives greyscale and
# the common colour-vision deficiencies; the categorical cycle is the
# accessibility-optimised eight.

import matplotlib
import matplotlib.pyplot as plt

SHEFFIELD = {
    'brand_violet': '#440099', 'dark_violet': '#24125E',
    'electric_violet': '#7000FF', 'powder_violet': '#A78CFA',
    'pale_violet': '#C8BBFF', 'wave_white': '#F8F8F9',
    'midnight_black': '#131E29', 'coral': '#E7004C', 'flamingo': '#FF6371',
    'peach': '#FF9664', 'pink': '#FF79E1', 'purple': '#981F92',
    'lavender': '#DAA8E2', 'teal': '#005A8F', 'aqua': '#00BBCC',
    'powder_blue': '#9ADBE8', 'peak_green': '#005750',
    'spearmint': '#3BD4AE', 'pastel_green': '#A1DED2',
}
CAT8 = [SHEFFIELD[k] for k in ('brand_violet','coral','teal','peak_green',
                               'peach','aqua','purple','spearmint')]

def set_style():
    plt.rcParams.update({
        'figure.dpi': 150, 'savefig.dpi': 600,
        'font.family': 'sans-serif',
        'font.size': 8, 'axes.labelsize': 8, 'axes.titlesize': 8,
        'xtick.labelsize': 7, 'ytick.labelsize': 7, 'legend.fontsize': 7,
        'axes.linewidth': 0.6, 'xtick.major.width': 0.6,
        'ytick.major.width': 0.6, 'xtick.direction': 'out',
        'ytick.direction': 'out',
        'axes.spines.top': False, 'axes.spines.right': False,
        'axes.grid': False, 'legend.frameon': False,
        'figure.facecolor': 'white', 'axes.facecolor': 'white',
        # v2.0.13a: NOT bbox='tight'. Cropping to content gives every figure a
        # different size, because the crop follows the longest axis label and
        # the number of legend rows. constrained_layout fits the content
        # inside a FIXED canvas instead, so a set of figures can sit side by
        # side in a manuscript without rescaling.
        'figure.constrained_layout.use': True,
        'figure.constrained_layout.h_pad': 0.04,
        'figure.constrained_layout.w_pad': 0.04,
        'axes.prop_cycle': plt.cycler(color=CAT8),
    })

W1, W2 = 3.35, 6.9      # single- and double-column inches
H1 = 3.1                # standard height, so a set of figures matches


def _axis_window(values, reference=None, pad=1.15, floor=0.05):
    """
    An upper limit that shows the DATA rather than the outliers.

    A percentile of the whole set is useless when n is small and the tail is
    long: on a 30-structure run one GII of 75.7 put the 97th percentile at
    33, so every real point collapsed into the corner and the figure read as
    blank. The window is therefore set from the REFERENCE population - the
    structures that passed every gate - and everything outside it is counted
    in an annotation rather than compressed into the frame.
    """
    v = pd.to_numeric(pd.Series(values), errors='coerce').dropna()
    ref = v if reference is None else pd.to_numeric(
        pd.Series(reference), errors='coerce').dropna()
    if not len(ref):
        ref = v
    if not len(ref):
        return floor
    return max(floor, float(ref.max()) * pad)

def fig_screen_overlap(per, ax=None):
    screens = [('anion packing','anion_packing_plausible'),
               ('cation packing','cation_packing_plausible'),
               ('bond-valence dist.','structure_bvs_geometry_plausible'),
               ('radii ratio','structure_core_geometry_plausible'),
               ('coordination','structure_cn_plausible')]
    sets={}
    for n,c in screens:
        if c in per.columns:            # absent is not the same as zero
            sets[n]=set(per.index[per[c].astype(str).str.lower().eq('false')])
    if 'n_sites_shift_proposed' in per:
        sets['wrong origin']=set(per.index[pd.to_numeric(
            per['n_sites_shift_proposed'],errors='coerce').fillna(0)>0])
    names=list(sets); tot=[len(sets[n]) for n in names]
    exc=[len(sets[n]-set().union(*[v for k,v in sets.items() if k!=n])) for n in names]
    o=np.argsort(tot)[::-1]
    names=[names[i] for i in o]; tot=[tot[i] for i in o]; exc=[exc[i] for i in o]
    if ax is None: _,ax=plt.subplots(figsize=(W1,2.3))
    y=np.arange(len(names))
    ax.barh(y,tot,color=SHEFFIELD['pale_violet'],height=0.62,zorder=2)
    ax.barh(y,exc,color=SHEFFIELD['brand_violet'],height=0.62,zorder=3)
    for i,(t,e) in enumerate(zip(tot,exc)):
        ax.text(t+max(tot)*0.015,i,f'{t}',va='center',ha='left',fontsize=7,
                color=SHEFFIELD['midnight_black'])
    ax.set_yticks(y); ax.set_yticklabels(names)
    ax.invert_yaxis(); ax.set_xlabel('Structures flagged')
    ax.set_xlim(0,max(tot)*1.14)
    import matplotlib.patches as _mp
    ax.legend(handles=[_mp.Patch(color=SHEFFIELD['brand_violet'],
                                 label='this screen alone'),
                       _mp.Patch(color=SHEFFIELD['pale_violet'],
                                 label='also caught elsewhere')],
              loc='upper center', bbox_to_anchor=(0.5, -0.28), ncol=2,
              handlelength=1.0, columnspacing=1.2, borderaxespad=0.0)
    return ax

def fig_gii_distribution(per, ax=None, tier_col='structure_pgrm_tier'):
    g=pd.to_numeric(per.get('gii_recommended_value',per.get('gii')),errors='coerce')
    # v2.0.25: the sound population is the three ACCEPT tiers, not the bare
    # one. gii_recommended_value above is what makes that safe: for the two
    # caveat tiers it is gii_site_averaged, which is the index they belong on.
    ok=per[tier_col].isin(PGRM_SOUND_TIERS) if tier_col in per else pd.Series(True,index=per.index)
    if ax is None: _,ax=plt.subplots(figsize=(W1,2.3))
    lo, hi = 0.0, 0.60
    bins = np.linspace(lo, hi, 31)
    a, b = g[ok].dropna(), g[~ok].dropna()
    # Values beyond the axis are COUNTED IN THE ANNOTATION, not piled into the
    # last bin: a clipped tail draws a spike that is an artefact of the clip.
    ax.hist([a[a <= hi], b[b <= hi]], bins=bins, stacked=True,
            color=[SHEFFIELD['brand_violet'], SHEFFIELD['coral']],
            label=[f'passed every gate  n = {len(a)}',
                   f'flagged or expunged  n = {len(b)}'], zorder=3)
    ax.set_xlabel('Global instability index / v.u.')
    ax.set_ylabel('Structures')
    ax.set_xlim(lo, hi)
    ax.legend(loc='upper center', bbox_to_anchor=(0.5, -0.28), ncol=1,
              handlelength=1.1, borderaxespad=0.0)
    _over = int((a > hi).sum()), int((b > hi).sum())
    if sum(_over):
        ax.text(0.97, 0.95, f'beyond {hi:g} v.u.:  {_over[0]} + {_over[1]}',
                transform=ax.transAxes, ha='right', va='top', fontsize=6.5,
                color=SHEFFIELD['midnight_black'])
    return ax

def fig_cation_vs_anion(per, ax=None, tier_col='structure_pgrm_tier',
                        gii_tol=0.30, anion_tol=0.20):
    """
    The cation and anion sides of the same bonds, on one pair of axes.

    Every bond contributes to one cation sum and one anion sum, so a cation
    discrepancy that CANCELS at the shared oxygen is a property of the
    parameters and one that does not is a property of the structure. The four
    quadrants are the four bvs_diagnosis labels; the guide lines are the
    tolerances that define them, so the figure and the column cannot disagree.
    """
    _yc = next((c for c in ('anion_deviation_mean_weighted',
                            'anion_deviation_mean') if c in per.columns), None)
    if _yc is None or 'gii' not in per.columns:
        return None
    x = pd.to_numeric(per['gii'], errors='coerce')
    y = pd.to_numeric(per[_yc], errors='coerce')
    if ax is None:
        _, ax = plt.subplots(figsize=(W1, H1))
    ok = (per[tier_col].isin(PGRM_SOUND_TIERS) if tier_col in per
          else pd.Series(True, index=per.index))

    # Axis window set from the bulk, with everything outside COUNTED rather
    # than squashed against the frame: three structures with a GII of 17 make
    # the other 935 unreadable.
    xhi = max(gii_tol * 2, _axis_window(x, reference=x[ok], floor=gii_tol * 2))
    _yr = y[ok].dropna()
    yhi = max(anion_tol * 2,
              (float(_yr.max()) * 1.15 if len(_yr) else anion_tol * 2))
    ylo = min(-anion_tol * 2,
              (float(_yr.min()) * 1.15 if len(_yr) else -anion_tol * 2))
    inside = x.le(xhi) & y.between(ylo, yhi)

    ax.axvline(gii_tol, color=SHEFFIELD['midnight_black'], lw=0.5, ls=':', zorder=1)
    for _h in (anion_tol, -anion_tol):
        ax.axhline(_h, color=SHEFFIELD['midnight_black'], lw=0.5, ls=':', zorder=1)
    ax.scatter(x[ok & inside], y[ok & inside], s=7, lw=0, alpha=0.7,
               c=SHEFFIELD['brand_violet'], zorder=3, label='passed every gate')
    ax.scatter(x[~ok & inside], y[~ok & inside], s=7, lw=0, alpha=0.7,
               c=SHEFFIELD['coral'], zorder=2, label='flagged or expunged')
    ax.set_xlim(0, xhi)
    ax.set_ylim(ylo, yhi)
    ax.set_xlabel('Cation GII / v.u.')
    ax.set_ylabel('Mean anion deviation / v.u.')

    _lab = dict(fontsize=6.5, color=SHEFFIELD['midnight_black'], zorder=4,
                style='italic')
    ax.text(0.03, 0.97, 'anions only', transform=ax.transAxes,
            ha='left', va='top', **_lab)
    ax.text(0.97, 0.97, 'both deviate', transform=ax.transAxes,
            ha='right', va='top', **_lab)
    ax.text(0.03, 0.03, 'both balance', transform=ax.transAxes,
            ha='left', va='bottom', **_lab)
    ax.text(0.97, 0.03, 'cations only', transform=ax.transAxes,
            ha='right', va='bottom', **_lab)
    _n_out = int((~inside).sum())
    _extra = f'   {_n_out} beyond the axes' if _n_out else ''
    ax.legend(loc='upper center', bbox_to_anchor=(0.5, -0.28), ncol=2,
              handlelength=0.9, columnspacing=1.2, borderaxespad=0.0,
              title=_extra.strip() or None, title_fontsize=6)
    return ax


def fig_gii_vs_wagii(per, ax=None):
    # v2.0.13a: the signature was (per, dfq=None, ax=None) and dfq was never
    # used, so eir_figures calling _fn(per, _ax) bound the AXIS to dfq. The
    # function then made its own figure, drew on that, and returned it - and
    # the axis that was saved stayed empty. The figure was written blank and
    # the call reported success.
    """
    The unweighted and occupancy-weighted instability indices against each
    other, with the identity line.

    They are the SAME quantity when every cation site carries the SAME
    occupancy - not, as the reports long said, when there is no anti-site
    disorder, and not only when every occupancy is 1.0. WAGII weights each
    site by its occupancy, so it is unequal weights that separate the two. A
    vacancy does that only where it leaves the sites at different occupancies,
    and on a structure with one cation site the weight cancels and the two
    indices are identical however vacant it is.

    Measured on the 539 rock salts: 308 carry one occupancy across every
    cation site and gii == wagii on all 308, the 42 that are not fully
    occupied included; of the 231 with unequal occupancies, 7 coincide. Full
    occupancy gives gii == wagii on 869 of 871 perovskites, 355 of 355
    pyrochlores and 335 of 338 spinels, while 1543 partially occupied spinels
    sit off the line.

    Distance from the line is therefore a direct measure of how much the
    unweighted index is inflated by sites that are not fully there, and the
    far outliers are worth opening: Li(0.93)Ti2O4 (ICSD 73020) reports a GII
    of 0.871 against a WAGII of 0.203, a factor of 4.3.
    """
    if 'gii' not in per.columns or 'wagii' not in per.columns:
        return None
    g = pd.to_numeric(per['gii'], errors='coerce')
    w = pd.to_numeric(per['wagii'], errors='coerce')
    ok = g.notna() & w.notna()
    if not ok.any():
        return None
    if ax is None:
        _, ax = plt.subplots(figsize=(W1, H1))

    # three causes, in order of severity of the effect
    anti = (per.get('has_antisite_disorder', pd.Series(False, index=per.index))
            .astype(str).str.lower().isin(['true', '1']))
    same = (g - w).abs() < 1e-9
    partial = ~same & ~anti

    # Window from the structures that PASSED THE GATES, not from those where
    # the two indices agree. A broken structure can be fully occupied and so
    # sit exactly on the line: ICSD 220506 has a La-O contact of 1.008 A, a
    # GII of 17.29, and gii == wagii. Using agreement as the reference let it
    # set the window at 19.9 while every other point sat below 1, and the
    # figure read as blank.
    _ref_mask = (per['structure_pgrm_tier'].isin(PGRM_SOUND_TIERS)
                 if 'structure_pgrm_tier' in per.columns else same)
    _ref = pd.concat([g[ok & _ref_mask], w[ok & _ref_mask]])
    hi = _axis_window(pd.concat([g[ok], w[ok]]), reference=_ref)
    ax.plot([0, hi], [0, hi], color=SHEFFIELD['midnight_black'], lw=0.6,
            ls='--', zorder=1)
    for _m, _c, _l in ((same, SHEFFIELD['brand_violet'], 'every site fully occupied'),
                       (partial, SHEFFIELD['aqua'], 'partial occupancy'),
                       (anti, SHEFFIELD['coral'], 'site shared between species')):
        _s = _m & ok & g.le(hi) & w.le(hi)
        if _s.any():
            ax.scatter(w[_s], g[_s], s=8, lw=0, alpha=0.75, c=_c,
                       label=f'{_l}  n = {int((_m & ok).sum())}', zorder=3)
    ax.set_xlim(0, hi)
    ax.set_ylim(0, hi)
    ax.set_aspect('equal', adjustable='box')
    ax.set_xlabel('WAGII, occupancy weighted / v.u.')
    ax.set_ylabel('GII, unweighted / v.u.')
    ax.text(0.97, 0.06, 'on the line: the two agree', transform=ax.transAxes,
            ha='right', fontsize=6.5, style='italic',
            color=SHEFFIELD['midnight_black'])
    _out = int((ok & ((g > hi) | (w > hi))).sum())
    ax.legend(loc='upper center', bbox_to_anchor=(0.5, -0.26), ncol=1,
              handlelength=0.9, borderaxespad=0.0,
              title=(f'{_out} beyond the axes' if _out else None),
              title_fontsize=6)
    return ax


def save_figure(fig, path_stem, formats=("pdf", "png")):
    """Write a figure for submission. PDF is the one to send."""
    _d = os.path.dirname(path_stem)
    if _d:
        os.makedirs(_d, exist_ok=True)
    written = []
    for _f in formats:
        _p = f"{path_stem}.{_f}"
        fig.savefig(_p, format=_f)
        written.append(_p)
    return written


def eir_figures(dfq, output_dir=None, stem="eir"):
    """
    The three diagnostics, each as its own single-column figure.

    Returns {name: figure}. Written to output_dir when one is given.
    """
    set_style()
    per = (build_structure_table(dfq).set_index("filename")
           if "build_structure_table" in globals()
           else dfq.drop_duplicates("filename").set_index("filename"))
    made, out = {}, {}
    for _name, _fn in (("screens", fig_screen_overlap),
                       ("gii", fig_gii_distribution),
                       ("cation_anion", fig_cation_vs_anion),
                       ("gii_vs_wagii", fig_gii_vs_wagii)):
        _f, _ax = plt.subplots(figsize=(W1, H1))
        if _fn(per, ax=_ax) is None:      # BY KEYWORD, deliberately
            plt.close(_f)
            print(f"  {_name}: the columns it needs are not present; skipped")
            continue
        made[_name] = _f
        if output_dir:
            out[_name] = save_figure(_f, os.path.join(output_dir,
                                                      f"{stem}_{_name}"))
    if out:
        print(f"  {len(out)} figure(s) written to {output_dir}")
    return made


print("Figures ready: eir_figures(dfq, output_dir). Palette: Sheffield brand.")
